'use strict'

const NIL = -1

/**
 * Fixed-capacity LRU cache backed by a hash map and an intrusive doubly
 * linked list stored in typed arrays. Every operation is O(1) expected.
 */
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity
    this.index = new Map() // key -> slot
    this.keys = new Array(capacity + 1)
    this.values = new Array(capacity + 1)
    this.prev = new Int32Array(capacity + 1)
    this.next = new Int32Array(capacity + 1)
    this.head = NIL // most recently used
    this.tail = NIL // least recently used
    this.free = [] // recycled slots
    this.nextSlot = 0
  }

  get size() {
    return this.index.size
  }

  get(key) {
    const slot = this.index.get(key)
    if (slot === undefined) return undefined
    this.#moveToFront(slot)
    return this.values[slot]
  }

  set(key, value) {
    let slot = this.index.get(key)
    if (slot !== undefined) {
      this.values[slot] = value
      this.#moveToFront(slot)
      return
    }
    slot = this.free.length > 0 ? this.free.pop() : this.nextSlot++
    this.keys[slot] = key
    this.values[slot] = value
    this.index.set(key, slot)
    this.#pushFront(slot)
    if (this.index.size > this.capacity) this.#removeSlot(this.tail)
  }

  delete(key) {
    const slot = this.index.get(key)
    if (slot === undefined) return false
    this.#removeSlot(slot)
    return true
  }

  #removeSlot(slot) {
    this.#unlink(slot)
    this.index.delete(this.keys[slot])
    this.keys[slot] = undefined
    this.values[slot] = undefined
    this.free.push(slot)
  }

  #pushFront(slot) {
    this.prev[slot] = NIL
    this.next[slot] = this.head
    if (this.head !== NIL) this.prev[this.head] = slot
    else this.tail = slot
    this.head = slot
  }

  #unlink(slot) {
    const p = this.prev[slot]
    const n = this.next[slot]
    if (p !== NIL) this.next[p] = n
    else this.head = n
    if (n !== NIL) this.prev[n] = p
    else this.tail = p
  }

  #moveToFront(slot) {
    if (slot === this.head) return
    this.#unlink(slot)
    this.#pushFront(slot)
  }
}

module.exports = { LRUCache }

'use strict'

const fs = require('node:fs')
const { LRUCache } = require('./lru.js')

function writeAll(fd, data) {
  const buf = Buffer.from(data)
  let off = 0
  while (off < buf.length) {
    try {
      off += fs.writeSync(fd, buf, off)
    } catch (err) {
      if (err.code !== 'EAGAIN') throw err
    }
  }
}

function main() {
  const input = fs.readFileSync(0, 'latin1')
  const lines = input.split('\n')
  const capacity = Number.parseInt(lines[0], 10)
  const cache = new LRUCache(capacity)
  const out = []

  for (let i = 1; i < lines.length; i++) {
    let line = lines[i]
    if (line.endsWith('\r')) line = line.slice(0, -1)
    if (line === '') continue
    const sp1 = line.indexOf(' ')
    const cmd = sp1 === -1 ? line : line.slice(0, sp1)
    switch (cmd) {
      case 'SET': {
        const sp2 = line.indexOf(' ', sp1 + 1)
        cache.set(line.slice(sp1 + 1, sp2), line.slice(sp2 + 1))
        break
      }
      case 'GET': {
        const value = cache.get(line.slice(sp1 + 1))
        out.push(value === undefined ? 'NULL' : value)
        break
      }
      case 'DEL':
        out.push(cache.delete(line.slice(sp1 + 1)) ? '1' : '0')
        break
      case 'SIZE':
        out.push(String(cache.size))
        break
      default:
        break // ignore unknown commands
    }
  }

  if (out.length > 0) writeAll(1, out.join('\n') + '\n')
}

main()
